        bycol=defaultdict(set); byrow=defaultdict(set)
        for br,bc_ in bps: bycol[bc_].add(br); byrow[br].add(bc_)
        for bc_,rs in bycol.items():
            loR = drs[min(rs)-1] if min(rs)>0 else 0; hiR = drs[max(rs)] if max(rs)<len(drs) else H
            for r in range(loR,hiR):
                if r in drs: continue
                for c in range(dcs[bc_-1] if bc_>0 else 0, dcs[bc_] if bc_<len(dcs) else W):
                    if c not in dcs: occ[v].add((r,c))
        for br,cs in byrow.items():
            loC = dcs[min(cs)-1] if min(cs)>0 else 0; hiC = dcs[max(cs)] if max(cs)<len(dcs) else W
            for c in range(loC,hiC):
                if c not in dcs:
                    for r in range(drs[br-1] if br>0 else 0, drs[br] if br<len(drs) else H):
                        occ[v].add((r,c))
    out=[[g[r][c] for c in range(W)] for r in range(H)]
    for r in range(H):
        for c in range(W):
            if g[r][c]==8: continue
            vs=[v for v in pc if (r,c) in occ[v]]
            if len(vs)>1: out[r][c]=6
            elif len(vs)==1: out[r][c]=vs[0]
    return out
